#!/usr/bin/env node
/**
 * generate-build-context.mjs
 *
 * Auto-regenerates state/shared/PRISM-BUILD-CONTEXT.md so every Claude session
 * (CLI + Desktop) can see, on top of "what PRISM IS", a current view of:
 *   - what was BUILT (last 7 days of commits, scope-tagged)
 *   - what's BEING BUILT now (active branch, milestone, peer-chat claims)
 *   - what's QUEUED next (roadmap top-5 + per-chat handoffs)
 *
 * Read by generate-claude-brief.mjs to fold into CLAUDE-BRIEF.md.
 * Read by SessionStart claude-brief-inject.mjs through the brief.
 * Regenerated by brief-drift-monitor.mjs hourly.
 *
 * Designed to fail open. If git is unavailable, claims dir is missing, or
 * roadmap is malformed — emit a section with a graceful fallback. The brief
 * must always render, even with partial data.
 *
 * Flags:
 *   --write        write to disk (default)
 *   --stdout       also emit content to stdout
 *   --quiet        suppress success message
 */
import { readFileSync, writeFileSync, existsSync, statSync, readdirSync } from "node:fs";
import { resolve, dirname, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { execSync } from "node:child_process";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PRISM_ROOT = resolve(__dirname, "..", "..");
const SHARED = resolve(PRISM_ROOT, "state", "shared");
const HANDOFF_DIR = resolve(SHARED, "handoffs");
const OUT = resolve(SHARED, "PRISM-BUILD-CONTEXT.md");
const ROADMAP_INDEX = resolve(PRISM_ROOT, "mcp-server", "data", "roadmap-index.json");
const CURRENT_POSITION = resolve(PRISM_ROOT, "state", "CURRENT_POSITION.md");
const AGENT_WORKBOARD = resolve(SHARED, "AGENT_WORKBOARD.md");

const args = new Set(process.argv.slice(2));
const FLAGS = {
  stdout: args.has("--stdout"),
  quiet: args.has("--quiet"),
};

const COMMIT_WINDOW_DAYS = 7;
const ROADMAP_TOP = 5;
const HANDOFF_TOP = 6;
const COMMIT_TOP = 25;
const CLAIMS_RECENT_MIN = 30;

function safeRead(path) {
  try {
    return existsSync(path) ? readFileSync(path, "utf8") : null;
  } catch {
    return null;
  }
}

function safeReadJson(path) {
  const raw = safeRead(path);
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return { _malformed: true };
  }
}

function safeListDir(path) {
  try {
    return existsSync(path) ? readdirSync(path) : [];
  } catch {
    return [];
  }
}

function safeGit(cmd) {
  try {
    return execSync(cmd, { cwd: PRISM_ROOT, encoding: "utf8", timeout: 8_000 });
  } catch (err) {
    return null;
  }
}

function recentCommits() {
  const out = safeGit(`git log --since="${COMMIT_WINDOW_DAYS} days ago" --no-merges --pretty=format:"%h%x09%ad%x09%s" --date=short -n ${COMMIT_TOP}`);
  if (!out) return { commits: [], note: "git unavailable" };
  const lines = out.split("\n").map((l) => l.trim()).filter(Boolean);
  if (lines.length === 0) return { commits: [], note: "no commits in last " + COMMIT_WINDOW_DAYS + " days" };
  return {
    commits: lines.map((l) => {
      const [hash, date, ...rest] = l.split("\t");
      return { hash, date, subject: rest.join("\t") };
    }),
    note: null,
  };
}

function currentBranch() {
  return (safeGit("git rev-parse --abbrev-ref HEAD") || "unknown").trim();
}

function aheadBehind() {
  const out = safeGit("git rev-list --left-right --count HEAD...@{u}") || "";
  const m = out.match(/(\d+)\s+(\d+)/);
  return m ? { ahead: parseInt(m[1], 10), behind: parseInt(m[2], 10) } : null;
}

function newEnginesSince() {
  const out = safeGit(`git log --since="${COMMIT_WINDOW_DAYS} days ago" --diff-filter=A --name-only --pretty=format: -- "mcp-server/src/engines/*.ts"`);
  if (!out) return [];
  const files = [...new Set(out.split("\n").map((f) => f.trim()).filter((f) => f.endsWith(".ts")))];
  return files.map((f) => basename(f, ".ts"));
}

function dispatcherEditsSince() {
  const out = safeGit(`git log --since="${COMMIT_WINDOW_DAYS} days ago" --name-only --pretty=format: -- "mcp-server/src/tools/dispatchers/*.ts"`);
  if (!out) return {};
  const counts = {};
  for (const line of out.split("\n")) {
    const f = line.trim();
    if (!f) continue;
    const name = basename(f, ".ts");
    counts[name] = (counts[name] || 0) + 1;
  }
  return counts;
}

function activeClaims() {
  const text = safeRead(AGENT_WORKBOARD);
  if (!text) return { claims: [], note: "AGENT_WORKBOARD.md not found" };
  const claimLines = text
    .split("\n")
    .filter((l) => /CLAIM|claiming|claim:|in_progress|🔒/i.test(l))
    .slice(0, 25);
  return {
    claims: claimLines.map((l) => l.trim()),
    note: claimLines.length === 0 ? "no active claims recorded" : null,
  };
}

function perChatHandoffs() {
  const files = safeListDir(HANDOFF_DIR).filter((f) => f.startsWith("HANDOFF-") && f.endsWith(".md"));
  if (files.length === 0) return { entries: [], note: "no per-chat handoffs found" };
  const entries = [];
  for (const fname of files) {
    const path = resolve(HANDOFF_DIR, fname);
    let mtime = 0;
    try { mtime = statSync(path).mtimeMs; } catch { /* skip */ }
    const content = safeRead(path) || "";
    const firstLine = content.split("\n").find((l) => l.trim().length > 0) || "(empty)";
    const resumeMatch = content.match(/Resume(?:\s*Directive)?[:\s]+([^\n]+)/i);
    entries.push({
      file: fname,
      mtime,
      headline: firstLine.replace(/^#+\s*/, "").slice(0, 120),
      resume: resumeMatch ? resumeMatch[1].slice(0, 120).trim() : null,
    });
  }
  entries.sort((a, b) => b.mtime - a.mtime);
  return { entries: entries.slice(0, HANDOFF_TOP), note: null };
}

function currentMilestone() {
  const text = safeRead(CURRENT_POSITION);
  if (!text) return { milestone: null, note: "CURRENT_POSITION.md not found" };
  const m = text.match(/(?:milestone|MS|scope)[:\s]+([A-Z0-9-]+)/i);
  const u = text.match(/U-[A-Z0-9-]+/);
  return {
    milestone: m ? m[1] : null,
    unit: u ? u[0] : null,
    note: null,
  };
}

function roadmapNext() {
  const idx = safeReadJson(ROADMAP_INDEX);
  if (!idx) return { next: [], note: "roadmap-index.json not found" };
  if (idx._malformed) return { next: [], note: "roadmap-index.json malformed JSON" };
  const units = Array.isArray(idx.units) ? idx.units : Array.isArray(idx) ? idx : [];
  const pending = units
    .filter((u) => u && u.status && /pending|queued|next/i.test(String(u.status)))
    .slice(0, ROADMAP_TOP);
  return {
    next: pending.map((u) => ({
      id: u.id || u.unit_id || u.name || "?",
      scope: u.scope || u.milestone || "?",
      title: u.title || u.subject || u.description || "?",
    })),
    note: pending.length === 0 ? "no pending units in roadmap-index" : null,
  };
}

function format() {
  const now = new Date().toISOString();
  const branch = currentBranch();
  const ab = aheadBehind();
  const branchSuffix = ab ? `  ·  ${ab.ahead} ahead / ${ab.behind} behind upstream` : "";

  const { commits, note: commitNote } = recentCommits();
  const newEngines = newEnginesSince();
  const dispatcherEdits = dispatcherEditsSince();
  const { claims, note: claimNote } = activeClaims();
  const { entries: handoffs, note: handoffNote } = perChatHandoffs();
  const { milestone, unit, note: milestoneNote } = currentMilestone();
  const { next: roadmap, note: roadmapNote } = roadmapNext();

  let md = `# PRISM-BUILD-CONTEXT — what we have + what we're building

**Auto-generated:** ${now}  ·  Source: \`generate-build-context.mjs\` (regenerated hourly + on SessionStart staleness)
**Window:** last ${COMMIT_WINDOW_DAYS} days

---

## Active branch

**\`${branch}\`**${branchSuffix}
${milestone ? `Current milestone: **${milestone}**` : ""}${unit ? ` · last unit: **${unit}**` : ""}
${milestoneNote ? `*(${milestoneNote})*` : ""}

`;

  md += `## What we just built (last ${COMMIT_WINDOW_DAYS} days)\n\n`;
  if (commitNote) {
    md += `*${commitNote}*\n\n`;
  } else {
    for (const c of commits) {
      md += `- \`${c.hash}\` (${c.date}) — ${c.subject}\n`;
    }
    md += "\n";
  }

  md += `### New engines added (${newEngines.length})\n\n`;
  if (newEngines.length === 0) {
    md += "*no new engines this window*\n\n";
  } else {
    md += newEngines.slice(0, 20).map((e) => `- ${e}`).join("\n") + "\n";
    if (newEngines.length > 20) md += `- … and ${newEngines.length - 20} more\n`;
    md += "\n";
  }

  md += `### Dispatcher edits this window\n\n`;
  const dispatcherList = Object.entries(dispatcherEdits).sort(([, a], [, b]) => b - a);
  if (dispatcherList.length === 0) {
    md += "*no dispatcher edits this window*\n\n";
  } else {
    for (const [name, count] of dispatcherList.slice(0, 12)) {
      md += `- ${name} (${count} commits)\n`;
    }
    md += "\n";
  }

  md += `## What we're building right now\n\n`;
  md += `### Active claims (peer chats — respect these)\n\n`;
  if (claimNote) {
    md += `*${claimNote}*\n\n`;
  } else {
    md += claims.slice(0, 12).map((c) => `- ${c.replace(/^[-*]\s*/, "")}`).join("\n") + "\n\n";
  }

  md += `### Per-chat handoffs (top ${HANDOFF_TOP})\n\n`;
  if (handoffNote) {
    md += `*${handoffNote}*\n\n`;
  } else {
    for (const h of handoffs) {
      const ageH = ((Date.now() - h.mtime) / 3_600_000).toFixed(1);
      md += `- **${h.file}** (${ageH}h ago) — ${h.headline}`;
      if (h.resume) md += `\n  - resume: ${h.resume}`;
      md += "\n";
    }
    md += "\n";
  }

  md += `## What's queued next (top ${ROADMAP_TOP} from roadmap)\n\n`;
  if (roadmapNote) {
    md += `*${roadmapNote}*\n\n`;
  } else {
    for (const r of roadmap) {
      md += `- **${r.id}** (${r.scope}) — ${r.title}\n`;
    }
    md += "\n";
  }

  md += `---

## How to use this file

Auto-injected via \`CLAUDE-BRIEF.md\` on SessionStart. Read before:
- creating any new engine, script, hook, or registry
- claiming a file (check active claims above to avoid stepping on a peer chat)
- proposing a roadmap unit (check what's already queued)

Refresh manually: \`/refresh-awareness\` (slash command), or
\`node ${resolve(__dirname, "generate-build-context.mjs").replace(/\\\\/g, "/")}\`
`;

  return md;
}

function main() {
  let content;
  try {
    content = format();
  } catch (err) {
    content = `# PRISM-BUILD-CONTEXT — generation failed\n\n**Error:** ${err.message}\n\nRun manually for diagnostics.\n`;
  }
  writeFileSync(OUT, content, "utf8");
  if (FLAGS.stdout) {
    process.stdout.write(content);
  }
  if (!FLAGS.quiet) {
    process.stderr.write(`Build context written to ${OUT} (${content.length} bytes)\n`);
  }
  process.exit(0);
}

main();
